"""Maybe deciders must receive normal declaration context preparation."""

import pytest

import factory


@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
def test_faker_decider_defaults(chance, expected):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker('boolean', chance_of_getting_true=chance, locale='en_US'),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == expected


@pytest.mark.parametrize('choice', [False, True])
def test_decider_context_is_unrolled(choice):
    class ContextDecider(factory.declarations.BaseDeclaration):
        def evaluate(self, instance, step, extra):
            return extra['choice']

    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            ContextDecider(choice=factory.LazyFunction(lambda: choice)),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['value'] == ('yes' if choice else 'no')
